    <section class="mx-auto max-w-3xl space-y-5"><flux:link :href="route('support.index')">← Tất cả liên hệ</flux:link><header class="flex flex-wrap items-start justify-between gap-3"><div><p class="eyebrow">Trao đổi với cửa hàng</p><h1 class="text-3xl font-semibold tracking-tight">{{ $conversation->subject }}</h1></div><span class="rounded-full px-3 py-1 text-xs {{ $conversation->status === 'open' ? 'bg-terrasse-sage/20 text-terrasse-ink' : 'bg-terrasse-ink/10 text-terrasse-ink/70' }}">{{ $conversation->status === 'open' ? 'Đang mở' : 'Đã đóng' }}</span></header>@include('reservations.feedback')<ol class="space-y-3" aria-label="Nội dung trao đổi">@foreach ($conversation->messages as $message) @php($own = $message->sender_id === auth()->id()) <li class="flex {{ $own ? 'justify-end' : 'justify-start' }}"><article class="max-w-xl rounded-xl border border-terrasse-ink/15 p-4 {{ $own ? 'bg-terrasse-sage/15' : 'bg-terrasse-paper' }}"><p class="text-sm font-semibold">{{ $own ? 'Bạn' : 'Cửa hàng' }}</p><p class="mt-2 whitespace-pre-wrap break-words">{{ $message->body }}</p><time class="mt-3 block text-xs text-terrasse-ink/60" datetime="{{ $message->created_at->toAtomString() }}">{{ $message->created_at->timezone('Asia/Ho_Chi_Minh')->format('H:i d/m/Y') }}</time></article></li>@endforeach</ol>@if ($conversation->status === 'open')<form method="POST" action="{{ route('support.reply', $conversation) }}" class="space-y-3 rounded-xl border border-terrasse-ink/15 bg-terrasse-paper p-4">@csrf<div><flux:textarea name="message" label="Phản hồi của bạn" rows="4" maxlength="2000" required>{{ old('message') }}</flux:textarea><flux:error name="message" /></div><flux:button type="submit" variant="primary">Gửi phản hồi</flux:button></form>@else<p class="rounded-xl border border-terrasse-ink/15 bg-terrasse-paper p-4 text-sm">Cuộc trao đổi đã được đóng. Nếu bạn cần thêm hỗ trợ, hãy tạo một tin nhắn mới.</p>@endif</section>
